<div class="admin-page-heading"><div><h1>کاربران</h1><p class="muted">جست‌وجو، مشاهده و ویرایش اطلاعات حساب‌ها</p></div><a class="primary" href="<?= $this->h($this->url('/users/new')) ?>">افزودن کاربر</a></div>
<form method="get" class="search section"><input type="hidden" name="r" value="/users"><label class="sr-only" for="q">جست‌وجوی کاربر</label><input id="q" name="q" value="<?= $this->h($query) ?>" placeholder="نام، شماره یا شناسه داخلی"><button class="primary">جست‌وجو</button></form>
<section class="compact-users section" aria-label="فهرست کاربران"><div class="compact-user-head"><span>کاربر</span><span>شناسه</span><span>وضعیت</span><span>عملیات</span></div>
<?php foreach($rows as $row): ?><article class="compact-user-row"><div><strong><?= $this->h($row['display_name']?:'نام تنظیم نشده') ?></strong><?php if($row['is_mentor']??false): ?><span class="mentor-role-badge">مرشد</span><?php endif; ?><small dir="ltr"><?= $this->h($row['phone']??'شماره ثبت نشده') ?></small></div><code dir="ltr"><?= $this->h($row['id']) ?></code><span class="tag"><?= !empty($row['deleted_at'])?'حذف‌شده':($row['status']==='active'?'فعال':'محدودشده') ?></span><a class="secondary" href="<?= $this->h($this->url('/users/edit?id='.$row['id'])) ?>">ویرایش اطلاعات</a></article><?php endforeach; ?><?php if(!$rows): ?><p class="empty">کاربری مطابق جست‌وجو پیدا نشد.</p><?php endif; ?></section>
<nav class="row section" aria-label="صفحه‌بندی"><?php if($page>1): ?><a class="secondary" href="<?= $this->h($this->url('/users?page='.($page-1).'&q='.rawurlencode($query))) ?>">قبلی</a><?php endif; ?><span>صفحه <?= $this->h($page) ?></span><?php if($more): ?><a class="secondary" href="<?= $this->h($this->url('/users?page='.($page+1).'&q='.rawurlencode($query))) ?>">بعدی</a><?php endif; ?></nav>
